  Class<?> voice=cl.loadClass("com.carrot.naverroute.VoicePlaceBridge");main(()->voice.getMethod("heard",String.class).invoke(null,"수학의힘신검단캠퍼스"));addFragment("com.tmapmobility.adot.ui.view.fragment.AdotSelectPlaceFragment");View footer=tag(navi.findViewById(android.R.id.content),"carrot-voice-place-search");check(footer!=null&&footer.isShown(),"Aria footer missing in navigation window");
